func parseHexColor(s string) (color.RGBA, error) {
	if len(s) != 6 {
		return color.RGBA{}, fmt.Errorf("invalid")
	}
	// check hex
	for _, c := range s {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
			return color.RGBA{}, fmt.Errorf("invalid")
		}
	}
	r, _ := strconv.ParseUint(s[0:2], 16, 8)
	g, _ := strconv.ParseUint(s[2:4], 16, 8)
	b, _ := strconv.ParseUint(s[4:6], 16, 8)
	return color.RGBA{uint8(r), uint8(g), uint8(b), 255}, nil
}

// BMP decoder for 24-bit uncompressed
func decodeBMP(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	if len(data) < 54 {
		return nil, fmt.Errorf("unknown format")
	}
	if data[0] != 'B' || data[1] != 'M' {
		return nil, fmt.Errorf("unknown format")
	}
	// offset to pixel array
	offset := int(uint32(data[10]) | uint32(data[11])<<8 | uint32(data[12])<<16 | uint32(data[13])<<24)
	headerSize := int(uint32(data[14]) | uint32(data[15])<<8 | uint32(data[16])<<16 | uint32(data[17])<<24)
	if headerSize != 40 {
		return nil, fmt.Errorf("unknown format")
	}
	w := int(int32(uint32(data[18]) | uint32(data[19])<<8 | uint32(data[20])<<16 | uint32(data[21])<<24))
	h := int(int32(uint32(data[22]) | uint32(data[23])<<8 | uint32(data[24])<<16 | uint32(data[25])<<24))
	planes := int(uint16(data[26]) | uint16(data[27])<<8)
	bpp := int(uint16(data[28]) | uint16(data[29])<<8)
	compression := int(uint32(data[30]) | uint32(data[31])<<8 | uint32(data[32])<<16 | uint32(data[33])<<24)
	if planes != 1 || (bpp != 24 && bpp != 32) || compression != 0 {
		// try to support 24 and 32
		if bpp != 24 && bpp != 32 {
			return nil, fmt.Errorf("unknown format")
		}
	}
	// For simplicity, handle bottom-up (h>0) ; if h<0 top-down
	topDown := false
	if h < 0 {
		topDown = true
		h = -h
	}
	if w <=0 || h <=0 {
		return nil, fmt.Errorf("unknown format")
	}
	rowSize := ((w*bpp + 31) / 32) * 4
	img := image.NewRGBA(image.Rect(0,0,w,h))
	for y := 0; y < h; y++ {
		var srcY int
		if topDown {
			srcY = y
		} else {
			srcY = h-1 - y
		}
		rowOffset := offset + srcY*rowSize
		if rowOffset+rowSize > len(data) {
			return nil, fmt.Errorf("unknown format")
		}
		for x := 0; x < w; x++ {
			if bpp == 24 {
				b := data[rowOffset + x*3]
				g := data[rowOffset + x*3 +1]
				r := data[rowOffset + x*3 +2]
				img.SetRGBA(x,y, color.RGBA{r,g,b,255})
			} else { // 32
				b := data[rowOffset + x*4]
				g := data[rowOffset + x*4 +1]
				r := data[rowOffset + x*4 +2]
				a := data[rowOffset + x*4 +3]
				img.SetRGBA(x,y, color.RGBA{r,g,b,a})
			}
		}
	}
	return img, nil
}

func loadImage(pathOrURL string) (image.Image, error) {
	var r io.ReadCloser
	if strings.HasPrefix(pathOrURL, "http://") || strings.HasPrefix(pathOrURL, "https://") {
		resp, err := http.Get(pathOrURL)
		if err != nil {
			return nil, err
		}
		if resp.StatusCode != 200 {
			resp.Body.Close()
			return nil, fmt.Errorf("Get \"%s\": status %d", pathOrURL, resp.StatusCode)
		}
		r = resp.Body
	} else {
		f, err := os.Open(pathOrURL)
		if err != nil {
			return nil, err
		}
		r = f
	}
	defer r.Close()
	// Try BMP first if extension .bmp
	if strings.HasSuffix(strings.ToLower(pathOrURL), ".bmp") {
		img, err := decodeBMP(r)
		if err == nil {
			return img, nil
		}
		// if BMP fails, try generic decode by reopening if file
		// For URL we already consumed reader, need to handle differently
		// For simplicity, if file, reopen
		if !strings.HasPrefix(pathOrURL, "http") {
			f2, err2 := os.Open(pathOrURL)
			if err2 != nil {
				return nil, err
			}
			defer f2.Close()
			img, _, err2 := image.Decode(f2)
			if err2 == nil {
				return img, nil
			}
			return nil, fmt.Errorf("unknown format")
		}
		return nil, fmt.Errorf("unknown format")
	}
	// Try generic decode
	img, _, err := image.Decode(r)
	if err == nil {
		return img, nil
	}
	// If generic fails and it's a file, try BMP
	if !strings.HasPrefix(pathOrURL, "http") {
		f2, err2 := os.Open(pathOrURL)
		if err2 != nil {
			return nil, err
		}
		defer f2.Close()
		bmpImg, err2 := decodeBMP(f2)
		if err2 == nil {
			return bmpImg, nil
		}
	}
	return nil, fmt.Errorf("unknown format")
}

func blend(c color.RGBA, matte color.RGBA) color.RGBA {
	// alpha blending: c over matte
	a := uint32(c.A)
	inv := uint32(255 - c.A)
	r := (uint32(c.R)*a + uint32(matte.R)*inv) / 255
	g := (uint32(c.G)*a + uint32(matte.G)*inv) / 255
	b := (uint32(c.B)*a + uint32(matte.B)*inv) / 255
	return color.RGBA{uint8(r), uint8(g), uint8(b), 255}
}

func getRGBA(img image.Image, x, y int, matte color.RGBA) color.RGBA {
	// get color and blend if needed
	c := img.At(x, y)
	// convert to RGBA
	r, g, b, a := c.RGBA()
	// r,g,b,a are 16-bit
	r8 := uint8(r >> 8)
	g8 := uint8(g >> 8)
	b8 := uint8(b >> 8)
	a8 := uint8(a >> 8)
	// If image is opaque, a8 may be 255 or 0? For image.RGBA with no alpha, it returns 0xffff.
	// For NRGBA etc.
	rgba := color.RGBA{r8, g8, b8, a8}
	if a8 == 255 {
		return rgba
	}
	// if alpha 0, return matte
	// else blend
	return blend(rgba, matte)
}

// Simple resize using bilinear (approx) to match original as close as possible
// For now, use simple bilinear with center sampling giving identity for same size
func resizeImage(img image.Image, dstW, dstH int, matte color.RGBA) image.Image {
	// dstW, dstH are desired dimensions in pixels
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()
	if srcW == dstW && srcH == dstH {
		// return copy with matte blending applied?
		// For identity, just return image with blending
		// Create new image with blended colors
		dst := image.NewRGBA(image.Rect(0,0,dstW,dstH))
		for y:=0; y<dstH; y++ {
			for x:=0; x<dstW; x++ {
				dst.Set(x,y, getRGBA(img, srcBounds.Min.X+x, srcBounds.Min.Y+y, matte))
			}
		}
		return dst
	}
	dst := image.NewRGBA(image.Rect(0,0,dstW,dstH))
	xRatio := float64(srcW) / float64(dstW)
	yRatio := float64(srcH) / float64(dstH)
	for dy := 0; dy < dstH; dy++ {
		for dx := 0; dx < dstW; dx++ {
			// simple bilinear with simple sampling (no 0.5)
			sx := float64(dx) * xRatio
			sy := float64(dy) * yRatio
			sx0 := int(sx)
			sy0 := int(sy)
			sx1 := sx0+1
			if sx1 >= srcW { sx1 = srcW-1 }
			if sx0 >= srcW { sx0 = srcW-1 }
			sy1 := sy0+1
			if sy1 >= srcH { sy1 = srcH-1 }
			if sy0 >= srcH { sy0 = srcH-1 }
			fx := sx - float64(sx0)
			fy := sy - float64(sy0)
			c00 := getRGBA(img, srcBounds.Min.X+sx0, srcBounds.Min.Y+sy0, matte)
			c10 := getRGBA(img, srcBounds.Min.X+sx1, srcBounds.Min.Y+sy0, matte)
			c01 := getRGBA(img, srcBounds.Min.X+sx0, srcBounds.Min.Y+sy1, matte)
			c11 := getRGBA(img, srcBounds.Min.X+sx1, srcBounds.Min.Y+sy1, matte)
			r := float64(c00.R)*(1-fx)*(1-fy) + float64(c10.R)*fx*(1-fy) + float64(c01.R)*(1-fx)*fy + float64(c11.R)*fx*fy
			g := float64(c00.G)*(1-fx)*(1-fy) + float64(c10.G)*fx*(1-fy) + float64(c01.G)*(1-fx)*fy + float64(c11.G)*fx*fy
			b := float64(c00.B)*(1-fx)*(1-fy) + float64(c10.B)*fx*(1-fy) + float64(c01.B)*(1-fx)*fy + float64(c11.B)*fx*fy
			dst.SetRGBA(dx, dy, color.RGBA{uint8(r), uint8(g), uint8(b), 255})
		}
	}
	return dst
}

// For fill: scale to fill (cover) then crop center
func fillImage(img image.Image, dstW, dstH int, matte color.RGBA) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()
	// scale factor to fill: max(dstW/srcW, dstH/srcH)
	fx := float64(dstW) / float64(srcW)
	fy := float64(dstH) / float64(srcH)
	f := fx
	if fy > f { f = fy }
	scaledW := int(float64(srcW) * f)
	scaledH := int(float64(srcH) * f)
	// first resize to scaledW x scaledH
	scaled := resizeImage(img, scaledW, scaledH, matte)
	// then crop center to dstW x dstH
	// create dst
	dst := image.NewRGBA(image.Rect(0,0,dstW,dstH))
	// offset to crop center
	offX := (scaledW - dstW) / 2
	offY := (scaledH - dstH) / 2
	for y:=0; y<dstH; y++ {
		for x:=0; x<dstW; x++ {
			dst.Set(x,y, scaled.At(offX+x, offY+y))
		}
	}
	return dst
}

