	if imagePath == "" {
		printHelp()
		os.Exit(2)
	}
	if tcSet != trSet {
		printHelp()
		os.Exit(2)
	}
	if tcSet && trSet {
		if tc <2 || tr <2 {
			printHelp()
			os.Exit(2)
		}
	}
	if dMode <0 || dMode >2 {
		printHelp()
		os.Exit(2)
	}
	if sMethod <0 || sMethod >2 {
		printHelp()
		os.Exit(2)
	}

	var cols, rows int
	if tcSet && trSet {
		cols = tc
		rows = tr
	} else {
		if isTerminal(os.Stdout.Fd()) {
			c, r, err := getTerminalSize()
			if err != nil {
				cols = 80
				rows = 22
			} else {
				cols = c
				rows = r
				if cols <2 { cols=80 }
				if rows <2 { rows=24 }
			}
		} else {
			cols = 80
			rows = 22
		}
	}

	img, err := loadImage(imagePath)
	if err != nil {
		printAsciiArt()
		fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s %s\n", getTimeStr(), err.Error())
		os.Exit(1)
	}
	if !matteSet {
		matte = color.RGBA{0,0,0,255}
	}

	var targetW, targetH int
	if dMode == 0 {
		targetW = cols
		targetH = rows*2
	} else {
		targetW = cols
		targetH = rows
	}

	var scaled image.Image
	var scaledW, scaledH int
	if sMethod == 0 {
		scaled = resizeImage(img, targetW, targetH, matte)
		scaledW = targetW
		scaledH = targetH
	} else if sMethod == 1 {
		scaled = fillImage(img, targetW, targetH, matte)
		scaledW = targetW
		scaledH = targetH
	} else {
		fitted, err := fitImage(img, targetW, targetH, matte)
		if err != nil {
			printAsciiArt()
			fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s %s\n", getTimeStr(), err.Error())
			os.Exit(1)
		}
		scaled = fitted
		scaledW = fitted.Bounds().Dx()
		scaledH = fitted.Bounds().Dy()
	}

	if scaledW <2 || scaledH <2 {
		printAsciiArt()
		fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s ANSImage: height or width must be >=2\n", getTimeStr())
		os.Exit(1)
	}

	if dMode == 0 {
		var outCols, outRows int
		if sMethod == 2 {
			outCols = scaledW
			outRows = (scaledH+1)/2
		} else {
			outCols = cols
			outRows = rows
		}
		for r:=0; r<outRows; r++ {
			var buf bytes.Buffer
			for c:=0; c<outCols; c++ {
				yTop := r*2
				yBottom := r*2+1
				var topColor, bottomColor color.RGBA
				if yTop < scaledH {
					topColor = getRGBA(scaled, scaled.Bounds().Min.X+c, scaled.Bounds().Min.Y+yTop, matte)
				} else {
					topColor = matte
				}
				if yBottom < scaledH {
					bottomColor = getRGBA(scaled, scaled.Bounds().Min.X+c, scaled.Bounds().Min.Y+yBottom, matte)
				} else {
					bottomColor = matte
				}
				if goOutput {
					buf.WriteString(fmt.Sprintf("\033[48;2;%d;%d;%dm\033[38;2;%d;%d;%dm\342\226\204", topColor.R, topColor.G, topColor.B, bottomColor.R, bottomColor.G, bottomColor.B))
				} else {
					buf.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm\342\226\204", topColor.R, topColor.G, topColor.B, bottomColor.R, bottomColor.G, bottomColor.B))
				}
			}
			if goOutput {
				lineStr := buf.String()
				escaped := strings.ReplaceAll(lineStr, "\x1b", "\\033")
				fmt.Printf("fmt.Print(\"%s\\033[0m\\n\")\n", escaped)
			} else {
				buf.WriteString("\x1b[0m\n")
				fmt.Print(buf.String())
			}
		}
	} else {
		var outCols, outRows int
		if sMethod == 2 {
			outCols = scaledW
			outRows = scaledH
		} else {
			outCols = cols
			outRows = rows
		}
		for r:=0; r<outRows; r++ {
			var buf bytes.Buffer
			for c:=0; c<outCols; c++ {
				pixColor := getRGBA(scaled, scaled.Bounds().Min.X+c, scaled.Bounds().Min.Y+r, matte)
				brightness := pixColor.R
				if pixColor.G > brightness { brightness = pixColor.G }
				if pixColor.B > brightness { brightness = pixColor.B }
				var ch string
				if dMode == 1 {
					switch {
					case brightness < 49:
						ch = " "
					case brightness < 101:
						ch = "░"
					case brightness < 153:
						ch = "▒"
					case brightness < 205:
						ch = "▓"
					default:
						ch = "█"
					}
				} else {
					switch {
					case brightness < 24:
						ch = " "
					case brightness < 47:
						ch = "."
					case brightness < 70:
						ch = ":"
					case brightness < 93:
						ch = ";"
					case brightness < 116:
						ch = "+"
					case brightness < 139:
						ch = "="
					case brightness < 162:
						ch = "x"
					case brightness < 185:
						ch = "X"
					case brightness < 208:
						ch = "$"
					case brightness < 231:
						ch = "&"
					default:
						ch = "#"
					}
				}
				if nobg {
					if goOutput {
						buf.WriteString(fmt.Sprintf("\033[38;2;%d;%d;%dm%s", pixColor.R, pixColor.G, pixColor.B, ch))
					} else {
						buf.WriteString(fmt.Sprintf("\x1b[38;2;%d;%d;%dm%s", pixColor.R, pixColor.G, pixColor.B, ch))
					}
				} else {
					if goOutput {
						buf.WriteString(fmt.Sprintf("\033[48;2;%d;%d;%dm\033[38;2;%d;%d;%dm%s", matte.R, matte.G, matte.B, pixColor.R, pixColor.G, pixColor.B, ch))
					} else {
						buf.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm%s", matte.R, matte.G, matte.B, pixColor.R, pixColor.G, pixColor.B, ch))
					}
				}
			}
			if goOutput {
				lineStr := buf.String()
				escaped := strings.ReplaceAll(lineStr, "\x1b", "\\033")
				fmt.Printf("fmt.Print(\"%s\\033[0m\\n\")\n", escaped)
			} else {
				buf.WriteString("\x1b[0m\n")
				fmt.Print(buf.String())
			}
		}
	}
}
GO
