func parseHexColor(s string) (color.RGBA, error) {
	if len(s) != 6 {
		return color.RGBA{}, fmt.Errorf("invalid")
	}
	for _, c := range s {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
			return color.RGBA{}, fmt.Errorf("invalid")
		}
	}
	r, _ := strconv.ParseUint(s[0:2], 16, 8)
	g, _ := strconv.ParseUint(s[2:4], 16, 8)
	b, _ := strconv.ParseUint(s[4:6], 16, 8)
	return color.RGBA{uint8(r), uint8(g), uint8(b), 255}, nil
}

func decodeBMP(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	if len(data) < 54 {
		return nil, fmt.Errorf("image: unknown format")
	}
	if data[0] != 'B' || data[1] != 'M' {
		return nil, fmt.Errorf("image: unknown format")
	}
	offset := int(uint32(data[10]) | uint32(data[11])<<8 | uint32(data[12])<<16 | uint32(data[13])<<24)
	headerSize := int(uint32(data[14]) | uint32(data[15])<<8 | uint32(data[16])<<16 | uint32(data[17])<<24)
	if headerSize != 40 {
		return nil, fmt.Errorf("image: unknown format")
	}
	w := int(int32(uint32(data[18]) | uint32(data[19])<<8 | uint32(data[20])<<16 | uint32(data[21])<<24))
	h := int(int32(uint32(data[22]) | uint32(data[23])<<8 | uint32(data[24])<<16 | uint32(data[25])<<24))
	planes := int(uint16(data[26]) | uint16(data[27])<<8)
	bpp := int(uint16(data[28]) | uint16(data[29])<<8)
	if planes != 1 || (bpp != 24 && bpp != 32) {
		if bpp != 24 && bpp != 32 {
			return nil, fmt.Errorf("image: unknown format")
		}
	}
	topDown := false
	if h < 0 {
		topDown = true
		h = -h
	}
	if w <=0 || h <=0 {
		return nil, fmt.Errorf("image: unknown format")
	}
	rowSize := ((w*bpp + 31) / 32) * 4
	img := image.NewRGBA(image.Rect(0,0,w,h))
	for y := 0; y < h; y++ {
		var srcY int
		if topDown {
			srcY = y
		} else {
			srcY = h-1 - y
		}
		rowOffset := offset + srcY*rowSize
		if rowOffset+rowSize > len(data) {
			return nil, fmt.Errorf("image: unknown format")
		}
		for x := 0; x < w; x++ {
			if bpp == 24 {
				bc := data[rowOffset + x*3]
				gc := data[rowOffset + x*3 +1]
				rc := data[rowOffset + x*3 +2]
				img.SetRGBA(x,y, color.RGBA{rc,gc,bc,255})
			} else {
				bc := data[rowOffset + x*4]
				gc := data[rowOffset + x*4 +1]
				rc := data[rowOffset + x*4 +2]
				ac := data[rowOffset + x*4 +3]
				img.SetRGBA(x,y, color.RGBA{rc,gc,bc,ac})
			}
		}
	}
	return img, nil
}

func loadImage(pathOrURL string) (image.Image, error) {
	var r io.ReadCloser
	if strings.HasPrefix(pathOrURL, "http://") || strings.HasPrefix(pathOrURL, "https://") {
		resp, err := http.Get(pathOrURL)
		if err != nil {
			return nil, err
		}
		if resp.StatusCode != 200 {
			resp.Body.Close()
			return nil, fmt.Errorf("Get \"%s\": status %d", pathOrURL, resp.StatusCode)
		}
		r = resp.Body
	} else {
		f, err := os.Open(pathOrURL)
		if err != nil {
			return nil, err
		}
		r = f
	}
	defer r.Close()
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("image: unknown format")
	}
	img, _, err := image.Decode(bytes.NewReader(data))
	if err == nil {
		return img, nil
	}
	bmpImg, err2 := decodeBMP(bytes.NewReader(data))
	if err2 == nil {
		return bmpImg, nil
	}
	return nil, fmt.Errorf("image: unknown format")
}

func blend(c color.RGBA, matte color.RGBA) color.RGBA {
	a := uint32(c.A)
	inv := uint32(255 - c.A)
	rr := (uint32(c.R)*a + uint32(matte.R)*inv) / 255
	gg := (uint32(c.G)*a + uint32(matte.G)*inv) / 255
	bb := (uint32(c.B)*a + uint32(matte.B)*inv) / 255
	return color.RGBA{uint8(rr), uint8(gg), uint8(bb), 255}
}

func getRGBA(img image.Image, x, y int, matte color.RGBA) color.RGBA {
	c := img.At(x, y)
	rr, gg, bb, aa := c.RGBA()
	r8 := uint8(rr >> 8)
	g8 := uint8(gg >> 8)
	b8 := uint8(bb >> 8)
	a8 := uint8(aa >> 8)
	rgba := color.RGBA{r8, g8, b8, a8}
	if a8 == 255 {
		return rgba
	}
	return blend(rgba, matte)
}

func resizeImage(img image.Image, dstW, dstH int, matte color.RGBA) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()
	dst := image.NewRGBA(image.Rect(0,0,dstW,dstH))
	if srcW == dstW && srcH == dstH {
		for y:=0; y<dstH; y++ {
			for x:=0; x<dstW; x++ {
				dst.Set(x,y, getRGBA(img, srcBounds.Min.X+x, srcBounds.Min.Y+y, matte))
			}
		}
		return dst
	}
	xRatio := float64(srcW) / float64(dstW)
	yRatio := float64(srcH) / float64(dstH)
	for dy := 0; dy < dstH; dy++ {
		for dx := 0; dx < dstW; dx++ {
			sx := float64(dx) * xRatio
			sy := float64(dy) * yRatio
			sx0 := int(sx)
			sy0 := int(sy)
			sx1 := sx0+1
			if sx1 >= srcW { sx1 = srcW-1 }
			if sx0 >= srcW { sx0 = srcW-1 }
			sy1 := sy0+1
			if sy1 >= srcH { sy1 = srcH-1 }
			if sy0 >= srcH { sy0 = srcH-1 }
			fx := sx - float64(sx0)
			fy := sy - float64(sy0)
			c00 := getRGBA(img, srcBounds.Min.X+sx0, srcBounds.Min.Y+sy0, matte)
			c10 := getRGBA(img, srcBounds.Min.X+sx1, srcBounds.Min.Y+sy0, matte)
			c01 := getRGBA(img, srcBounds.Min.X+sx0, srcBounds.Min.Y+sy1, matte)
			c11 := getRGBA(img, srcBounds.Min.X+sx1, srcBounds.Min.Y+sy1, matte)
			rf := float64(c00.R)*(1-fx)*(1-fy) + float64(c10.R)*fx*(1-fy) + float64(c01.R)*(1-fx)*fy + float64(c11.R)*fx*fy
			gf := float64(c00.G)*(1-fx)*(1-fy) + float64(c10.G)*fx*(1-fy) + float64(c01.G)*(1-fx)*fy + float64(c11.G)*fx*fy
			bf := float64(c00.B)*(1-fx)*(1-fy) + float64(c10.B)*fx*(1-fy) + float64(c01.B)*(1-fx)*fy + float64(c11.B)*fx*fy
			dst.SetRGBA(dx, dy, color.RGBA{uint8(rf), uint8(gf), uint8(bf), 255})
		}
	}
	return dst
}

func fillImage(img image.Image, dstW, dstH int, matte color.RGBA) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()
	fx := float64(dstW) / float64(srcW)
	fy := float64(dstH) / float64(srcH)
	f := fx
	if fy > f { f = fy }
	scaledW := int(float64(srcW) * f)
	scaledH := int(float64(srcH) * f)
	if scaledW <1 { scaledW=1 }
	if scaledH <1 { scaledH=1 }
	scaled := resizeImage(img, scaledW, scaledH, matte)
	dst := image.NewRGBA(image.Rect(0,0,dstW,dstH))
	offX := (scaledW - dstW) / 2
	offY := (scaledH - dstH) / 2
	for y:=0; y<dstH; y++ {
		for x:=0; x<dstW; x++ {
			dst.Set(x,y, scaled.At(offX+x, offY+y))
		}
	}
	return dst
}

func fitImage(img image.Image, dstW, dstH int, matte color.RGBA) (image.Image, error) {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()
	fx := float64(dstW) / float64(srcW)
	fy := float64(dstH) / float64(srcH)
	f := fx
	if fy < f { f = fy }
	scaledW := int(float64(srcW) * f)
	scaledH := int(float64(srcH) * f)
	if scaledW <2 || scaledH <2 {
		return nil, fmt.Errorf("ANSImage: height or width must be >=2")
	}
	scaled := resizeImage(img, scaledW, scaledH, matte)
	return scaled, nil
}

func getTimeStr() string {
	return time.Now().Format("2006/01/02 15:04:05")
}

func isTerminal(fd uintptr) bool {
	type winsize struct {
		Row, Col, Xpixel, Ypixel uint16
	}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&winsize{})))
	if errno != 0 {
		return false
	}
	return true
}

func getTerminalSize() (int,int,error) {
	type winsize struct {
		Row, Col, Xpixel, Ypixel uint16
	}
	ws := &winsize{}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(os.Stdout.Fd()), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
	if errno != 0 {
		_, _, errno2 := syscall.Syscall(syscall.SYS_IOCTL, uintptr(os.Stdin.Fd()), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
		if errno2 != 0 {
			return 0,0, fmt.Errorf("not tty")
		}
	}
	return int(ws.Col), int(ws.Row), nil
}

