		os.Exit(2)
	}
	var dMode = 0
	var sMethod = 0
	var matte color.RGBA = color.RGBA{0,0,0,255}
	var matteSet = false
	var nobg = false
	var goOutput = false
	var tcSet = false
	var trSet = false
	var tc = 0
	var tr = 0
	var credits = false
	var showVersion = false
	var helpFlag = false
	var imagePath string
	i:=0
	for i < len(args) {
		a := args[i]
		if strings.HasPrefix(a, "--") {
			a = "-" + a[2:]
		}
		switch a {
		case "-credits":
			credits = true
			i++
		case "-version":
			showVersion = true
			i++
		case "-help", "-h":
			helpFlag = true
			i++
		case "-go":
			goOutput = true
			i++
