				printHelp()
				os.Exit(2)
			}
			dMode = d
			i+=2
		case "-s":
			if i+1 >= len(args) {
				printHelp()
				os.Exit(2)
			}
			val := args[i+1]
			s, err := strconv.Atoi(val)
			if err != nil {
				printHelp()
				os.Exit(2)
			}
			sMethod = s
			i+=2
		case "-m":
			if i+1 >= len(args) {
				printHelp()
				os.Exit(2)
			}
			val := args[i+1]
			if strings.HasPrefix(val, "-") {
				printAsciiArt()
				fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s matte color : %s is not a hex-color\n", getTimeStr(), val)
				os.Exit(1)
			}
			c, err := parseHexColor(val)
			if err != nil {
				printAsciiArt()
				fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s matte color : %s is not a hex-color\n", getTimeStr(), val)
				os.Exit(1)
			}
			matte = c
			matteSet = true
			i+=2
		case "-tc":
			if i+1 >= len(args) {
				printHelp()
				os.Exit(2)
			}
			val := args[i+1]
			v, err := strconv.Atoi(val)
			if err != nil {
				printHelp()
				os.Exit(2)
			}
			tc = v
			tcSet = true
			i+=2
		case "-tr":
			if i+1 >= len(args) {
				printHelp()
				os.Exit(2)
			}
			val := args[i+1]
			v, err := strconv.Atoi(val)
			if err != nil {
				printHelp()
				os.Exit(2)
			}
			tr = v
			trSet = true
			i+=2
		default:
			if strings.HasPrefix(a, "-d=") {
				val := strings.TrimPrefix(a, "-d=")
				d, err := strconv.Atoi(val)
				if err != nil {
					printHelp()
					os.Exit(2)
				}
				dMode = d
				i++
			} else if strings.HasPrefix(a, "-s=") {
				val := strings.TrimPrefix(a, "-s=")
				s, err := strconv.Atoi(val)
				if err != nil {
					printHelp()
					os.Exit(2)
				}
				sMethod = s
				i++
			} else if strings.HasPrefix(a, "-tc=") {
				val := strings.TrimPrefix(a, "-tc=")
				v, err := strconv.Atoi(val)
				if err != nil {
					printHelp()
					os.Exit(2)
				}
				tc = v
				tcSet = true
				i++
			} else if strings.HasPrefix(a, "-tr=") {
				val := strings.TrimPrefix(a, "-tr=")
				v, err := strconv.Atoi(val)
				if err != nil {
					printHelp()
					os.Exit(2)
				}
				tr = v
				trSet = true
				i++
			} else if strings.HasPrefix(a, "-m=") {
				val := strings.TrimPrefix(a, "-m=")
				c, err := parseHexColor(val)
				if err != nil {
					printAsciiArt()
					fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s matte color : %s is not a hex-color\n", getTimeStr(), val)
					os.Exit(1)
				}
				matte = c
				matteSet = true
				i++
			} else if strings.HasPrefix(a, "-") {
