func parseHexColor(s string) (color.RGBA, error) {
	if len(s) != 6 {
		return color.RGBA{}, fmt.Errorf("invalid")
	}
	for _, c := range s {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
			return color.RGBA{}, fmt.Errorf("invalid")
		}
	}
	r, _ := strconv.ParseUint(s[0:2], 16, 8)
	g, _ := strconv.ParseUint(s[2:4], 16, 8)
	b, _ := strconv.ParseUint(s[4:6], 16, 8)
	return color.RGBA{uint8(r), uint8(g), uint8(b), 255}, nil
}

func decodeBMP(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	if len(data) < 54 {
		return nil, fmt.Errorf("image: unknown format")
	}
	if data[0] != 'B' || data[1] != 'M' {
		return nil, fmt.Errorf("image: unknown format")
	}
	offset := int(uint32(data[10]) | uint32(data[11])<<8 | uint32(data[12])<<16 | uint32(data[13])<<24)
	headerSize := int(uint32(data[14]) | uint32(data[15])<<8 | uint32(data[16])<<16 | uint32(data[17])<<24)
	if headerSize != 40 {
		return nil, fmt.Errorf("image: unknown format")
	}
	w := int(int32(uint32(data[18]) | uint32(data[19])<<8 | uint32(data[20])<<16 | uint32(data[21])<<24))
	h := int(int32(uint32(data[22]) | uint32(data[23])<<8 | uint32(data[24])<<16 | uint32(data[25])<<24))
	planes := int(uint16(data[26]) | uint16(data[27])<<8)
	bpp := int(uint16(data[28]) | uint16(data[29])<<8)
	if planes != 1 || (bpp != 24 && bpp != 32) {
		if bpp != 24 && bpp != 32 {
			return nil, fmt.Errorf("image: unknown format")
		}
	}
	topDown := false
	if h < 0 {
		topDown = true
		h = -h
	}
	if w <=0 || h <=0 {
		return nil, fmt.Errorf("image: unknown format")
	}
	rowSize := ((w*bpp + 31) / 32) * 4
	img := image.NewRGBA(image.Rect(0,0,w,h))
	for y := 0; y < h; y++ {
		var srcY int
		if topDown {
			srcY = y
		} else {
			srcY = h-1 - y
		}
		rowOffset := offset + srcY*rowSize
		if rowOffset+rowSize > len(data) {
			return nil, fmt.Errorf("image: unknown format")
		}
		for x := 0; x < w; x++ {
			if bpp == 24 {
				bc := data[rowOffset + x*3]
				gc := data[rowOffset + x*3 +1]
				rc := data[rowOffset + x*3 +2]
				img.SetRGBA(x,y, color.RGBA{rc,gc,bc,255})
			} else {
				bc := data[rowOffset + x*4]
				gc := data[rowOffset + x*4 +1]
				rc := data[rowOffset + x*4 +2]
				ac := data[rowOffset + x*4 +3]
				img.SetRGBA(x,y, color.RGBA{rc,gc,bc,ac})
			}
		}
	}
	return img, nil
}

func loadImage(pathOrURL string) (image.Image, error) {
	var r io.ReadCloser
	if strings.HasPrefix(pathOrURL, "http://") || strings.HasPrefix(pathOrURL, "https://") {
		resp, err := http.Get(pathOrURL)
		if err != nil {
			return nil, err
		}
		if resp.StatusCode != 200 {
			resp.Body.Close()
			return nil, fmt.Errorf("Get \"%s\": status %d", pathOrURL, resp.StatusCode)
		}
		r = resp.Body
	} else {
		f, err := os.Open(pathOrURL)
		if err != nil {
			return nil, err
		}
		r = f
	}
	defer r.Close()
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("image: unknown format")
	}
	img, _, err := image.Decode(bytes.NewReader(data))
	if err == nil {
		return img, nil
	}
	bmpImg, err2 := decodeBMP(bytes.NewReader(data))
	if err2 == nil {
		return bmpImg, nil
	}
	return nil, fmt.Errorf("image: unknown format")
}

func blend(c color.RGBA, matte color.RGBA) color.RGBA {
	a := uint32(c.A)
	inv := uint32(255 - c.A)
	rr := (uint32(c.R)*a + uint32(matte.R)*inv) / 255
	gg := (uint32(c.G)*a + uint32(matte.G)*inv) / 255
	bb := (uint32(c.B)*a + uint32(matte.B)*inv) / 255
	return color.RGBA{uint8(rr), uint8(gg), uint8(bb), 255}
}

func getRGBA(img image.Image, x, y int, matte color.RGBA) color.RGBA {
	c := img.At(x, y)
	rr, gg, bb, aa := c.RGBA()
	r8 := uint8(rr >> 8)
	g8 := uint8(gg >> 8)
	b8 := uint8(bb >> 8)
	a8 := uint8(aa >> 8)
	rgba := color.RGBA{r8, g8, b8, a8}
	if a8 == 255 {
		return rgba
	}
	return blend(rgba, matte)
}

// Improved resize: for downscale use box averaging, for upscale use bilinear
func resizeImage(img image.Image, dstW, dstH int, matte color.RGBA) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()
	dst := image.NewRGBA(image.Rect(0,0,dstW,dstH))
	// If same size, just copy with blending
	if srcW == dstW && srcH == dstH {
		for y:=0; y<dstH; y++ {
			for x:=0; x<dstW; x++ {
				dst.Set(x,y, getRGBA(img, srcBounds.Min.X+x, srcBounds.Min.Y+y, matte))
			}
		}
		return dst
	}
	// Determine if downscaling in each dimension
	xRatio := float64(srcW) / float64(dstW)
	yRatio := float64(srcH) / float64(dstH)
	for dy := 0; dy < dstH; dy++ {
		for dx := 0; dx < dstW; dx++ {
			// Compute source region
			sx0f := float64(dx) * xRatio
			sx1f := float64(dx+1) * xRatio
			sy0f := float64(dy) * yRatio
			sy1f := float64(dy+1) * yRatio
			sx0 := int(sx0f)
			sx1 := int(sx1f)
			if sx1 <= sx0 { sx1 = sx0+1 }
			sy0 := int(sy0f)
			sy1 := int(sy1f)
			if sy1 <= sy0 { sy1 = sy0+1 }
			if sx0 <0 { sx0=0 }
			if sy0 <0 { sy0=0 }
			if sx1 > srcW { sx1 = srcW }
			if sy1 > srcH { sy1 = srcH }
			// Average over region
			var rSum, gSum, bSum, count uint64
			for sy:=sy0; sy<sy1; sy++ {
				for sx:=sx0; sx<sx1; sx++ {
					c := getRGBA(img, srcBounds.Min.X+sx, srcBounds.Min.Y+sy, matte)
					rSum += uint64(c.R)
					gSum += uint64(c.G)
					bSum += uint64(c.B)
					count++
				}
			}
			if count==0 {
				// fallback to bilinear simple for upscale case where region <1
				sx := float64(dx) * xRatio
				sy := float64(dy) * yRatio
				sx0b := int(sx)
				sy0b := int(sy)
				sx1b := sx0b+1
				if sx1b >= srcW { sx1b = srcW-1 }
				if sx0b >= srcW { sx0b = srcW-1 }
				sy1b := sy0b+1
				if sy1b >= srcH { sy1b = srcH-1 }
				if sy0b >= srcH { sy0b = srcH-1 }
				fx := sx - float64(sx0b)
				fy := sy - float64(sy0b)
				c00 := getRGBA(img, srcBounds.Min.X+sx0b, srcBounds.Min.Y+sy0b, matte)
				c10 := getRGBA(img, srcBounds.Min.X+sx1b, srcBounds.Min.Y+sy0b, matte)
				c01 := getRGBA(img, srcBounds.Min.X+sx0b, srcBounds.Min.Y+sy1b, matte)
				c11 := getRGBA(img, srcBounds.Min.X+sx1b, srcBounds.Min.Y+sy1b, matte)
				rf := float64(c00.R)*(1-fx)*(1-fy) + float64(c10.R)*fx*(1-fy) + float64(c01.R)*(1-fx)*fy + float64(c11.R)*fx*fy
				gf := float64(c00.G)*(1-fx)*(1-fy) + float64(c10.G)*fx*(1-fy) + float64(c01.G)*(1-fx)*fy + float64(c11.G)*fx*fy
				bf := float64(c00.B)*(1-fx)*(1-fy) + float64(c10.B)*fx*(1-fy) + float64(c01.B)*(1-fx)*fy + float64(c11.B)*fx*fy
				dst.SetRGBA(dx, dy, color.RGBA{uint8(rf), uint8(gf), uint8(bf), 255})
			} else {
				dst.SetRGBA(dx, dy, color.RGBA{uint8(rSum/count), uint8(gSum/count), uint8(bSum/count), 255})
			}
		}
	}
	return dst
}

func fillImage(img image.Image, dstW, dstH int, matte color.RGBA) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()
	fx := float64(dstW) / float64(srcW)
	fy := float64(dstH) / float64(srcH)
	f := fx
	if fy > f { f = fy }
	scaledW := int(float64(srcW) * f)
	scaledH := int(float64(srcH) * f)
	if scaledW <1 { scaledW=1 }
	if scaledH <1 { scaledH=1 }
	scaled := resizeImage(img, scaledW, scaledH, matte)
	dst := image.NewRGBA(image.Rect(0,0,dstW,dstH))
	offX := (scaledW - dstW) / 2
	offY := (scaledH - dstH) / 2
	for y:=0; y<dstH; y++ {
		for x:=0; x<dstW; x++ {
			dst.Set(x,y, scaled.At(offX+x, offY+y))
		}
	}
	return dst
}

func fitImage(img image.Image, dstW, dstH int, matte color.RGBA) (image.Image, error) {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()
	fx := float64(dstW) / float64(srcW)
	fy := float64(dstH) / float64(srcH)
	f := fx
	if fy < f { f = fy }
	scaledW := int(float64(srcW) * f)
	scaledH := int(float64(srcH) * f)
	if scaledW <2 || scaledH <2 {
		return nil, fmt.Errorf("ANSImage: height or width must be >=2")
	}
	scaled := resizeImage(img, scaledW, scaledH, matte)
	return scaled, nil
}

func getTimeStr() string {
	return time.Now().Format("2006/01/02 15:04:05")
}

func isTerminal(fd uintptr) bool {
	type winsize struct {
		Row, Col, Xpixel, Ypixel uint16
	}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&winsize{})))
	if errno != 0 {
		return false
	}
	return true
}

func getTerminalSize() (int,int,error) {
	type winsize struct {
		Row, Col, Xpixel, Ypixel uint16
	}
	ws := &winsize{}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(os.Stdout.Fd()), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
	if errno != 0 {
		_, _, errno2 := syscall.Syscall(syscall.SYS_IOCTL, uintptr(os.Stdin.Fd()), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
		if errno2 != 0 {
			return 0,0, fmt.Errorf("not tty")
		}
	}
	return int(ws.Col), int(ws.Row), nil
}

func main() {
	args := os.Args[1:]
	if len(args) == 0 {
		printHelp()
		os.Exit(2)
	}
	var dMode = 0
	var sMethod = 0
	var matte color.RGBA = color.RGBA{0,0,0,255}
	var matteSet = false
	var nobg = false
	var goOutput = false
	var tcSet = false
	var trSet = false
	var tc = 0
	var tr = 0
	var credits = false
	var showVersion = false
	var helpFlag = false
	var imagePath string
	i:=0
	for i < len(args) {
		a := args[i]
		if strings.HasPrefix(a, "--") {
			a = "-" + a[2:]
		}
		switch a {
		case "-credits":
			credits = true
			i++
		case "-version":
			showVersion = true
			i++
		case "-help", "-h":
			helpFlag = true
			i++
		case "-go":
			goOutput = true
			i++
		case "-nobg":
			nobg = true
			i++
		case "-d":
			if i+1 >= len(args) {
				printHelp()
				os.Exit(2)
			}
			val := args[i+1]
			d, err := strconv.Atoi(val)
			if err != nil {
				printHelp()
				os.Exit(2)
			}
			dMode = d
			i+=2
		case "-s":
			if i+1 >= len(args) {
				printHelp()
				os.Exit(2)
			}
			val := args[i+1]
			s, err := strconv.Atoi(val)
			if err != nil {
				printHelp()
				os.Exit(2)
			}
			sMethod = s
			i+=2
		case "-m":
			if i+1 >= len(args) {
				printHelp()
				os.Exit(2)
			}
			val := args[i+1]
			if strings.HasPrefix(val, "-") {
				printAsciiArt()
				fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s matte color : %s is not a hex-color\n", getTimeStr(), val)
				os.Exit(1)
			}
			c, err := parseHexColor(val)
			if err != nil {
				printAsciiArt()
				fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s matte color : %s is not a hex-color\n", getTimeStr(), val)
				os.Exit(1)
			}
			matte = c
			matteSet = true
			i+=2
		case "-tc":
			if i+1 >= len(args) {
				printHelp()
				os.Exit(2)
			}
			val := args[i+1]
			v, err := strconv.Atoi(val)
			if err != nil {
				printHelp()
				os.Exit(2)
			}
			tc = v
			tcSet = true
			i+=2
		case "-tr":
			if i+1 >= len(args) {
				printHelp()
				os.Exit(2)
			}
			val := args[i+1]
			v, err := strconv.Atoi(val)
			if err != nil {
				printHelp()
				os.Exit(2)
			}
			tr = v
			trSet = true
			i+=2
		default:
			if strings.HasPrefix(a, "-d=") {
				val := strings.TrimPrefix(a, "-d=")
				d, err := strconv.Atoi(val)
				if err != nil {
					printHelp()
					os.Exit(2)
				}
				dMode = d
				i++
			} else if strings.HasPrefix(a, "-s=") {
				val := strings.TrimPrefix(a, "-s=")
				s, err := strconv.Atoi(val)
				if err != nil {
					printHelp()
					os.Exit(2)
				}
				sMethod = s
				i++
			} else if strings.HasPrefix(a, "-tc=") {
				val := strings.TrimPrefix(a, "-tc=")
				v, err := strconv.Atoi(val)
				if err != nil {
					printHelp()
					os.Exit(2)
				}
				tc = v
				tcSet = true
				i++
			} else if strings.HasPrefix(a, "-tr=") {
				val := strings.TrimPrefix(a, "-tr=")
				v, err := strconv.Atoi(val)
				if err != nil {
					printHelp()
					os.Exit(2)
				}
				tr = v
				trSet = true
				i++
			} else if strings.HasPrefix(a, "-m=") {
				val := strings.TrimPrefix(a, "-m=")
				c, err := parseHexColor(val)
				if err != nil {
					printAsciiArt()
					fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s matte color : %s is not a hex-color\n", getTimeStr(), val)
					os.Exit(1)
				}
				matte = c
				matteSet = true
				i++
			} else if strings.HasPrefix(a, "-") {
				printHelp()
				os.Exit(2)
			} else {
				if imagePath == "" {
					imagePath = a
				} else {
					printHelp()
					os.Exit(2)
				}
				i++
			}
		}
	}

	if helpFlag {
		printHelp()
		os.Exit(2)
	}
	if showVersion {
		fmt.Println(version)
		os.Exit(0)
	}
	if credits {
		printCredits()
		os.Exit(0)
	}
	if imagePath == "" {
		printHelp()
		os.Exit(2)
	}
	if tcSet != trSet {
		printHelp()
		os.Exit(2)
	}
	if tcSet && trSet {
		if tc <2 || tr <2 {
			printHelp()
			os.Exit(2)
		}
	}
	if dMode <0 || dMode >2 {
		printHelp()
		os.Exit(2)
	}
	if sMethod <0 || sMethod >2 {
		printHelp()
		os.Exit(2)
	}

	var cols, rows int
	if tcSet && trSet {
		cols = tc
		rows = tr
	} else {
		if isTerminal(os.Stdout.Fd()) {
			c, r, err := getTerminalSize()
			if err != nil {
				cols = 80
				rows = 22
			} else {
				cols = c
				rows = r
				if cols <2 { cols=80 }
				if rows <2 { rows=24 }
			}
		} else {
			cols = 80
			rows = 22
		}
	}

	img, err := loadImage(imagePath)
	if err != nil {
		printAsciiArt()
		fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s %s\n", getTimeStr(), err.Error())
		os.Exit(1)
	}
	if !matteSet {
		matte = color.RGBA{0,0,0,255}
	}

	var targetW, targetH int
	if dMode == 0 {
		targetW = cols
		targetH = rows*2
	} else {
		targetW = cols
		targetH = rows
	}

	var scaled image.Image
	var scaledW, scaledH int
	if sMethod == 0 {
		scaled = resizeImage(img, targetW, targetH, matte)
		scaledW = targetW
		scaledH = targetH
	} else if sMethod == 1 {
		scaled = fillImage(img, targetW, targetH, matte)
		scaledW = targetW
		scaledH = targetH
	} else {
		fitted, err := fitImage(img, targetW, targetH, matte)
		if err != nil {
			printAsciiArt()
			fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s %s\n", getTimeStr(), err.Error())
			os.Exit(1)
		}
		scaled = fitted
		scaledW = fitted.Bounds().Dx()
		scaledH = fitted.Bounds().Dy()
	}

	if scaledW <2 || scaledH <2 {
		printAsciiArt()
		fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s ANSImage: height or width must be >=2\n", getTimeStr())
		os.Exit(1)
	}

	if dMode == 0 {
		var outCols, outRows int
		if sMethod == 2 {
			outCols = scaledW
			outRows = (scaledH+1)/2
		} else {
			outCols = cols
			outRows = rows
		}
		for r:=0; r<outRows; r++ {
			var buf bytes.Buffer
			for c:=0; c<outCols; c++ {
				yTop := r*2
				yBottom := r*2+1
				var topColor, bottomColor color.RGBA
				if yTop < scaledH {
					topColor = getRGBA(scaled, scaled.Bounds().Min.X+c, scaled.Bounds().Min.Y+yTop, matte)
				} else {
					topColor = matte
				}
